@OutputTimeUnit(TimeUnit.MILLISECONDS)
@Warmup(iterations = 5, time = 1, timeUnit = TimeUnit.SECONDS)
@Measurement(iterations = 10, time = 1, timeUnit = TimeUnit.SECONDS)
@Fork(1)
@State(Scope.Thread)
public class MaybeFlatMapNotificationBenchmark {

    // Mappers used for all three scenarios – they are cheap and deterministic.
    private final Function<Integer, MaybeSource<String>> successMapper = v -> Maybe.just("value:" + v);

    private final Function<Throwable, MaybeSource<String>> errorMapper = e -> Maybe.just("error:" + e.getMessage());

    private final Supplier<MaybeSource<String>> completeSupplier = () -> Maybe.just("completed");

    /**
     * Benchmark the onSuccess → mapper path.
